<?php

/**
 * Onboarding, step 1: request a compliance CSID for the CSR generated by GeneratorCertificate.php.
 *
 * Requires sevaske/zatca-api 3.x: composer require sevaske/zatca-api
 */

require __DIR__.'/../../vendor/autoload.php';

use Sevaske\ZatcaApi\Client;
use Sevaske\ZatcaApi\Exception\ApiException;
use Sevaske\ZatcaApi\Exception\ZatcaException;

try {
    $csr = file_get_contents(__DIR__.'/output/certificate.csr');

    // Client::sandbox() accepts the test OTP "123345"; in simulation / production use the OTP from the Fatoora portal.
    $zatca = Client::sandbox();

    $complianceCsid = $zatca->onboarding()
        ->requestComplianceCsid($csr, '123345')
        ->toComplianceCsid();

    // Keep the credentials together with the private key of the CSR (output/private.pem):
    // the certificate signs the compliance samples, the credentials authorize the compliance checks.
    $outputFile = __DIR__.'/output/compliance-csid.json';
    file_put_contents($outputFile, json_encode($complianceCsid->toArray(), JSON_PRETTY_PRINT));

    echo "Compliance CSID saved to {$outputFile}\n";
    echo "Certificate (base64 DER) for signing the compliance samples:\n".$complianceCsid->getCertificate()."\n";

    // Step 2: sign one sample of every document type with this certificate and check it:
    // $zatca->compliance($complianceCsid)->checkInvoice(SignedInvoice::fromXml($signedXml));
    // Step 3: RequestProductionCertificate.php
} catch (ApiException $e) {
    echo 'ZATCA error: '.$e->getMessage()."\n"; // e.g. "... The provided OTP is invalid [Invalid-OTP]"
} catch (ZatcaException $e) {
    echo 'Error: '.$e->getMessage()."\n";
}
